295	    ].join('\n');
296	
297	    const response = await provider.chatCompletion({
298	      messages: [
299	        {
300	          role: 'system',
301	          content: prompt
302	        },
303	        {
304	          role: 'user',
305	          content: userContent
306	        }
307	      ],
308	      temperature: 0.3,
309	      maxTokens: 800
310	    });
311	
312	    if (!response?.content) return null;
313	    return String(response.content).trim();
314	  } catch (error) {
315	    log.warn('Unable to generate AI assistance tips. Continuing without them.', {
316	      error: error instanceof Error ? error.message : String(error)
317	    });
318	    return null;
319	  }
320	}
321	
322	function extractTips(markdown: string | null) {
323	  const sections = {
324	    checklist: '',
325	    modelCard: '',
326	    riskFile: ''
327	  };
328	
329	  if (!markdown) {
330	    return sections;
331	  }
332	
333	  type SectionKey = keyof typeof sections;
334	  const markers: Record<string, SectionKey> = {
335	    'checklist tips': 'checklist',
336	    'model card tips': 'modelCard',
337	    'risk file tips': 'riskFile'
338	  };
339	
340	  let current: SectionKey | null = null;
341	  const lines = markdown.split('\n');
342	  for (const line of lines) {
343	    const normalized = line.trim().toLowerCase();
344	    const key = normalized.replace(/[:\s]+$/u, '');
345	    const sectionKey = markers[key];
346	    if (sectionKey) {
347	      current = sectionKey;
348	      sections[sectionKey] = '';
349	      continue;
350	    }
351	    if (current) {
352	      sections[current] = `${sections[current]}${line}\n`;
353	    }
354	  }
