#!/usr/bin/env node

import fs from 'fs';
import os from 'os';
import path from 'path';
import { generateReport, runEvaluations, writeReport } from './packages/frai-core/src/eval/index.js';

const tmpdir = fs.mkdtempSync(path.join(os.tmpdir(), 'test-'));

const evaluations = runEvaluations({
  outputs: ['Hello', 'World'],
  references: ['hello', 'world']
});

const report = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5, exact_match_fail: 0.9 },
  generatedAt: '2024-01-01T00:00:00.000Z'
});

// Remove the invalid threshold
const reportFixed = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5 },
  generatedAt: '2024-01-01T00:00:00.000Z'
});

const markdownPath = writeReport({
  report: reportFixed,
  format: 'markdown',
  reportPath: path.join(tmpdir, 'report.md')
});

console.log('Markdown report written to:', markdownPath);
console.log('\nReport content:');
console.log('='.repeat(60));
const content = fs.readFileSync(markdownPath, 'utf8');
console.log(content);
console.log('='.repeat(60));

// Verify thresholds section exists
if (content.includes('## Thresholds')) {
  console.log('\n✓ Thresholds section found in markdown report');
} else {
  console.log('\n✗ Thresholds section NOT found in markdown report');
}

if (content.includes('exact_match')) {
  console.log('✓ Metric name found in thresholds section');
} else {
  console.log('✗ Metric name NOT found in thresholds section');
}

if (content.includes('PASS')) {
  console.log('✓ Status found in thresholds section');
} else {
  console.log('✗ Status NOT found in thresholds section');
}

// Cleanup
fs.rmSync(tmpdir, { recursive: true, force: true });

